from dataclasses import dataclass

@dataclass
class RunningStats:
    count: int = 0
    total: float = 0.0
    sq_total: float = 0.0
    min: float = None
    max: float = None

    def update(self, x):
        self.count += 1
        self.total += x
        self.sq_total += x * x
        if self.min is None or x < self.min:
            self.min = x
        if self.max is None or x > self.max:
            self.max = x

    @property
    def mean(self):
        return self.total / self.count if self.count else 0.0

    @property
    def variance(self):
        if self.count < 2:
            return 0.0
        m = self.mean
        return self.sq_total / self.count - m * m

    def snapshot(self):
        return {'count': self.count, 'mean': self.mean, 'variance': self.variance,
                'min': self.min, 'max': self.max}

def make_running_stats():
    return RunningStats()
